-- Push keys live in Supabase Vault, created where they're used, so no secret is ever copied by hand:
--   push_secret   generated here by the database; the notifications trigger sends it to /api/push, which
--                 checks it with push_keys() before sending anything
--   vapid_public / vapid_private   generated by /api/push the first time it runs (first writer wins,
--                 never replaced), read back only by push_keys() with the right push_secret
-- /api/push needs no environment variables.

do $$ begin
  if not exists (select 1 from vault.secrets where name = 'push_secret') then
    perform vault.create_secret(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'push_secret', 'Shared by the notifications trigger and /api/push');
  end if;
end $$;

-- The public key browsers subscribe with (public by design)
create or replace function public.push_vapid() returns text
language sql stable security definer set search_path = public as $$
  select decrypted_secret from vault.decrypted_secrets where name = 'vapid_public';
$$;

-- One-time setup from /api/push: stores the key pair only if none exists yet
create or replace function public.push_vapid_init(pub text, priv text) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from vault.secrets where name = 'vapid_public') then return false; end if;
  if pub !~ '^[A-Za-z0-9_-]{87}$' or priv !~ '^[A-Za-z0-9_-]{43}$' then raise exception 'Invalid key' using errcode = 'P0001'; end if;
  perform vault.create_secret(priv, 'vapid_private', 'Web Push signing key (P-256), used by /api/push');
  perform vault.create_secret(pub, 'vapid_public', 'Web Push public key, browsers subscribe with it');
  return true;
end $$;

-- /api/push reads the key pair, but only with the secret the trigger gave it
create or replace function public.push_keys(secret text) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when secret is not null and secret = (select decrypted_secret from vault.decrypted_secrets where name = 'push_secret')
    then jsonb_build_object('pub', (select decrypted_secret from vault.decrypted_secrets where name = 'vapid_public'),
                            'priv', (select decrypted_secret from vault.decrypted_secrets where name = 'vapid_private')) end;
$$;

revoke execute on function public.push_vapid(), public.push_vapid_init(text, text), public.push_keys(text) from public;
grant execute on function public.push_vapid(), public.push_vapid_init(text, text), public.push_keys(text) to anon, authenticated;
